/bin/bash -lc "python3 -B - <<'PY'
import copy, json
from pathlib import Path
output=Path('enrichment/v7/work/t1_s087_20261009/out/luna-max/c606.jsonl')
fixes={
    **{('MAWARDI-FULL:v6p126',r):['أشد'] for r in range(17,22)},
    ('MAWARDI-FULL:v6p150#2',11):['عظامه'],
    **{('MAWARDI-FULL:v6p206',r):['*'] for r in range(12,20)},
}
lines=output.read_text().splitlines(keepends=True)
changed=0
for i,line in enumerate(lines):
    obj=json.loads(line); before=copy.deepcopy(obj)
    for n,row in enumerate(obj['rows'],1):
        key=(obj['loc'],n)
        if key in fixes:
            row['words']=fixes[key]; changed+=1
    for old,new in zip(before['rows'],obj['rows']):
        assert {k:v for k,v in old.items() if k"'!='"'words'}=={k:v for k,v in new.items() if k"'!='"'words'}
    assert {k:v for k,v in before.items() if k"'!='"'rows'}=={k:v for k,v in obj.items() if k"'!='"'rows'}
    if before"'!=obj:
        lines[i]=json.dumps(obj,ensure_ascii=False,separators=('"',',':'))+'\\n'
assert changed==14
output.write_text(''.join(lines))
print('Repaired 14 flagged word tags; all other fields preserved.')
PY"

